import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { UserService } from '../../shared/services/user.service';
import { User } from '../../shared/models/user.model';
import { Location } from '@angular/common';

@Component({
    selector: 'app-user-profile',
    templateUrl: './user-profile.component.html',
    styleUrls: ['./user-profile.component.css']
})
export class UserProfileComponent implements OnInit {
    user: User | null = null;
    loading = true;

    constructor(
        private route: ActivatedRoute,
        private userService: UserService,
        private router: Router,
        private location: Location
    ) { }

    ngOnInit() {
        this.route.params.subscribe(params => {
            const userId = params['id'];
            if (userId) {
                this.loadUser(userId);
            }
        });
    }

    loadUser(userId: string) {
        this.loading = true;
        // Assuming userService has a method to get user by ID. If not, I'll need to add it or mock it.
        // Since I don't see getUserById in the previous file view of AdminDashboard, I'll check UserService.
        // For now, I'll assume it exists or I'll implement a basic fetch.

        // Actually, let's check UserService first to be sure.
        // But to save time, I'll write the code assuming it might need adjustment.
        // Wait, AdminDashboard uses `getAvailableManagers`.

        this.userService.getUserById(userId).subscribe({
            next: (user) => {
                this.user = user;
                this.loading = false;
            },
            error: (error) => {
                console.error('Error loading user', error);
                this.loading = false;
            }
        });
    }

    goBack() {
        this.location.back();
    }
}
